use crate::*;
use schemars::schema_for;

#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
pub struct ToolSpec {
    pub name: String,
    pub description: String,
    pub read_only: bool,
    pub input_schema: Value,
    pub output_schema: Value,
}

#[derive(Debug, Clone, Copy)]
pub struct ToolSummary {
    pub name: &'static str,
    pub description: &'static str,
    pub read_only: bool,
}

fn spec<T: JsonSchema, R: JsonSchema>(name: &str, description: &str, read_only: bool) -> ToolSpec {
    ToolSpec {
        name: name.into(),
        description: description.into(),
        read_only,
        input_schema: serde_json::to_value(schema_for!(T)).expect("schema is JSON"),
        output_schema: serde_json::to_value(schema_for!(Response<R>)).expect("schema is JSON"),
    }
}

mod sealed {
    pub trait Sealed {}
}
/// A registered tool owns its name and associated request/response types.
pub trait Tool: sealed::Sealed {
    type Input: serde::Serialize + serde::de::DeserializeOwned + JsonSchema;
    type Output: serde::Serialize + serde::de::DeserializeOwned + JsonSchema;
    const NAME: &'static str;
    const READ_ONLY: bool;
}
macro_rules! tools {
    ($( $marker:ident: ($input:ty, $output:ty, $name:literal, $description:literal, $read_only:literal) ),* $(,)?) => {
        $(
            pub struct $marker;
            impl sealed::Sealed for $marker {}
            impl Tool for $marker {
                type Input = $input;
                type Output = $output;
                const NAME: &'static str = $name;
                const READ_ONLY: bool = $read_only;
            }
        )*
        /// Typed in-process invocation generated from the public registry.
        /// This is not an additional wire envelope or a published schema.
        #[allow(clippy::large_enum_variant)]
        pub enum ToolRequest { $( $marker($input), )* }
        impl ToolRequest {
            pub fn decode(name: &str, value: Value) -> Result<Self, opencut_contracts::EditorError> {
                match name {
                    $( $name => serde_json::from_value(value).map(Self::$marker)
                        .map_err(|e| opencut_contracts::EditorError::new("INVALID_ARGUMENT", e.to_string())), )*
                    _ => Err(opencut_contracts::EditorError::new("NOT_FOUND", format!("Unknown operation: {name}"))),
                }
            }
            /// Compatibility adapter for the native facade during use-case migration.
            pub fn into_parts(self) -> Result<(&'static str, Value), opencut_contracts::EditorError> {
                match self { $( Self::$marker(input) => serde_json::to_value(input)
                    .map(|value| ($name, value))
                    .map_err(|e| opencut_contracts::EditorError::new("INTERNAL_ERROR", e.to_string())), )* }
            }
        }
        pub fn is_tool(name: &str) -> bool { matches!(name, $($name)|*) }
        pub fn tool_summaries() -> &'static [ToolSummary] {
            const SUMMARIES: &[ToolSummary] = &[$(ToolSummary {
                name: $name,
                description: $description,
                read_only: $read_only,
            }),*];
            SUMMARIES
        }
        pub fn tool_spec(name: &str) -> Option<ToolSpec> {
            match name {
                $($name => Some(spec::<$input, $output>($name, $description, $read_only)),)*
                _ => None,
            }
        }
        pub fn tool_specs() -> Vec<ToolSpec> {
            vec![$(spec::<$input, $output>($name, $description, $read_only)),*]
        }
    }
}
